def solve_marmots_problem():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    # Create a list of tuples (cost, day, is_preparation)
    costs = [(a[i], i, True) for i in range(n)] + [(b[i], i, False) for i in range(n)]

    # Sort costs in ascending order
    costs.sort()

    total_cost = 0
    prep_count = 0
    print_count = 0

    for cost, day, is_prep in costs:
        if is_prep:
            if prep_count < k:
                total_cost += cost
                prep_count += 1
        else:
            if print_count < k:
                total_cost += cost
                print_count += 1

    print(total_cost)

if __name__ == "__main__":
    solve_marmots_problem()
